import os
from alibabacloud_green20220322 import models
from alibabacloud_tea_openapi import models as open_api_models
from alibabacloud_green20220322.client import Client as GreenClient
from alibabacloud_tea_util import models as util_models

def score_text_safety(text: str) -> dict:
    config = open_api_models.Config(
        access_key_id=os.environ.get('ALIBABA_CLOUD_ACCESS_KEY_ID'),
        access_key_secret=os.environ.get('ALIBABA_CLOUD_ACCESS_KEY_SECRET'),
        region_id='cn-hangzhou'
    )
    client = GreenClient(config)

    request = models.TextModerationRequest(
        service='baselineCheck',
        service_parameters={
            'content': text,
            'dataId': str(hash(text))
        }
    )

    runtime = util_models.RuntimeOptions()
    try:
        response = client.text_moderation_with_options(request, runtime)
        result = response.body.to_map()

        if result.get('Code') == 200:
            data = result.get('Data', {})
            risk_level = data.get('riskLevel', 'PASS')
            risk_score = float(data.get('confidence', 0.0)) / 100.0 if data.get('confidence') else 0.0

            return {
                'safe': risk_level == 'PASS',
                'score': risk_score,
                'risk_level': risk_level,
                'details': data.get('labels', [])
            }
        else:
            return {
                'safe': True,
                'score': 0.0,
                'risk_level': 'ERROR',
                'details': []
            }
    except Exception:
        return {
            'safe': True,
            'score': 0.0,
            'risk_level': 'ERROR',
            'details': []
        }
